base('Normalization','GAAP and analyst-adjusted common earnings',48);head('Normalization',6,['Ticker','GAAP LTM common','After-tax adjustment','Adjusted common','LTM diluted shares','Adjusted EPS','Adjusted P/E','Reason','Rationale']);banks.forEach((x,i)=>{let r=i+7,a=i+29;v('Normalization','C'+r,x.ticker);f('Normalization','D'+r,'='+b(x.ticker,'R','common_income'));f('Normalization','E'+r,`=Assumptions!D${a}`);f('Normalization','F'+r,safe(`D${r}+E${r}`,['D'+r,'E'+r]));f('Normalization','G'+r,'='+b(x.ticker,'R','shares_diluted'));f('Normalization','H'+r,ratio('F'+r,'G'+r));f('Normalization','I'+r,`=IF(AND(ISNUMBER(H${r}),H${r}>0),'Multiples'!D${r}/H${r},"n.a.")`);f('Normalization','J'+r,`=Assumptions!E${a}`);f('Normalization','K'+r,`=Assumptions!F${a}`);});fmt('Normalization','D7:G16',money);fmt('Normalization','H7:H16',usd);fmt('Normalization','I7:I16',times);chart('Normalization',['C6:C16','D6:D16','F6:F16'],'GAAP and adjusted common income (USDm)','T7:AE25');analysis('Normalization',23,['The primary CCA retains GAAP common earnings. The default analyst adjustment is zero.','A positive after-tax value adds back a charge; a negative value removes a gain. Source and tax treatment are required.','Credit provisions are operating costs of a bank and should not be removed merely because they are unusually large.','Truist disposals and Capital One acquisitions require event-specific accounting review before normalization.','Adjusted EPS and P/E remain separate from the primary GAAP outputs.']);
